const chatInput = $input.first().json.chatInput || '';

// Match pattern: anything_digits (e.g. user@example.com_1723622400000)
const sessionPattern = /^(.+)_(\d{10,15})$/;
const match = chatInput.trim().match(sessionPattern);

let sessionId = '';
if (match) {
  // The entire chatInput is a session_id — student pasted it as first message
  sessionId = chatInput.trim();
}

return [{
  json: {
    chatInput: chatInput,
    session_id: sessionId
  }
}];

const row = $input.first().json;
const sessionId = $('Extract Session ID').first().json.session_id || '';
const chatInput = $('Extract Session ID').first().json.chatInput || '';

// Valid consent: row has a session_id, consent_given is true, withdrawn is false
const hasRow = !!row.session_id;
const consentGiven = row.consent_given === true || row.consent_given === 'true';
const notWithdrawn = row.withdrawn === false || row.withdrawn === 'false';
const hasConsent = hasRow && consentGiven && notWithdrawn;

return [{
  json: {
    has_consent: hasConsent,
    chatInput: chatInput,
    session_id: sessionId
  }
}];
